insert into public.words (id, word, romanization, category, secondary_category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, likes, saves, translations) values
('478', '진대', 'Jin-dae', 'new-slang', null, '''진지한 대화''의 줄임말 — 농담 빼고 속 얘기하는 대화', '{"de": "Kurz für „ernstes Gespräch“ — ein Gespräch ohne Witze", "en": "Short for “serious talk” — a heart-to-heart with the jokes off", "es": "Abreviatura de “conversación seria”: hablar en serio, sin bromas", "ja": "「真剣な会話」の略 — 冗談抜きで本音を話すこと", "vi": "Viết tắt của “cuộc nói chuyện nghiêm túc” — tâm sự không đùa cợt"}'::jsonb, null, '[{"type": "명사", "definition": "''진지한 대화''의 앞 글자를 딴 줄임말. 농담이나 장난 없이 고민·진로·관계처럼 무게 있는 이야기를 속마음까지 터놓고 나누는 대화를 말한다. ''진대하다'', ''진대 좀 하자'', ''진대중''처럼 쓰며, 가볍고 재미있는 수다를 뜻하는 ''잼얘''와 반대되는 말처럼 쓰인다.", "definition_i18n": {"de": "Kurzform aus den Anfangssilben von 진지한 대화 („ernstes Gespräch“): ein Gespräch ohne Witze über Gewichtiges wie Sorgen, Zukunft oder Beziehungen, bei dem man ehrlich sagt, was man denkt. Man sagt 진대하다, 진대 좀 하자 („lass uns ernst reden“) oder 진대중 („gerade im ernsten Gespräch“); es dient als Gegenstück zu 잼얘, lockerem Plaudern.", "en": "Formed from the first syllables of 진지한 대화, “serious conversation”: a talk with the jokes switched off, about weighty things like worries, the future or a relationship, where you say what you really think. It is used as 진대하다 (to have a serious talk), 진대 좀 하자 (“let''s talk seriously”) or 진대중 (“in a serious talk right now”), and works as the opposite of 잼얘, fun small talk.", "es": "Formada con las primeras sílabas de 진지한 대화, “conversación seria”: una charla sin bromas sobre asuntos de peso como preocupaciones, el futuro o una relación, en la que dices lo que de verdad piensas. Se usa como 진대하다, 진대 좀 하자 (“hablemos en serio”) o 진대중 (“en plena charla seria”), y funciona como lo contrario de 잼얘, la charla divertida.", "ja": "「진지한 대화(真剣な会話)」の頭文字を取った略語。冗談抜きで悩み・進路・人間関係のような重い話を本音で交わす会話。「진대하다」「진대 좀 하자(ちょっと真面目に話そう)」「진대중(真剣な話し中)」のように使い、楽しい雑談を指す「잼얘」の反対語のように使われる。", "vi": "Ghép từ âm đầu của 진지한 대화, “cuộc nói chuyện nghiêm túc”: trò chuyện không đùa giỡn về chuyện hệ trọng như lo lắng, tương lai hay các mối quan hệ, nói thật lòng mình. Dùng như 진대하다, 진대 좀 하자 (“nói chuyện nghiêm túc chút nhé”) hay 진대중 (“đang nói chuyện nghiêm túc”), và được xem là trái nghĩa với 잼얘 — chuyện phiếm vui vẻ."}, "examples": [{"kor": "오늘 저녁에 잠깐 진대 좀 하자. 할 얘기 있어.", "eng": "Let''s have a serious talk tonight. There''s something I need to tell you.", "ja": "今夜ちょっと真面目に話そう。話したいことがあるんだ。", "es": "Esta noche hablemos en serio un momento. Tengo algo que decirte.", "vi": "Tối nay mình nói chuyện nghiêm túc chút nhé. Tớ có chuyện muốn nói.", "de": "Lass uns heute Abend kurz ernst reden. Ich muss dir was sagen."}, {"kor": "어제 성적 때문에 엄마랑 진대했어.", "eng": "I had a serious talk with my mom about my grades yesterday.", "ja": "昨日、成績のことで母と真剣に話した。", "es": "Ayer tuve una conversación seria con mi madre por mis notas.", "vi": "Hôm qua tớ nói chuyện nghiêm túc với mẹ vì chuyện điểm số.", "de": "Gestern hatte ich wegen meiner Noten ein ernstes Gespräch mit meiner Mutter."}]}]'::jsonb, '''진지한 대화''의 앞 글자를 딴 줄임말. 2013년 기사에 10대들이 ''엄마랑 진대 때림''처럼 쓰는 말로 소개될 만큼 오래전부터 청소년 사이에서 쓰였다. 지금은 연애·인간관계 콘텐츠에서 ''회피형 애인과 진대하는 법''처럼 쓰일 만큼 일상어가 됐고, 카톡 상태메시지에 ''진대중''으로 적기도 한다. 최초 사용처는 확인되지 않는다.', '{"de": "Kurzform aus den Anfangssilben von 진지한 대화. Schon ein Artikel von 2013 zitiert Teenager mit „엄마랑 진대 때림“ („hatte ein ernstes Gespräch mit Mama“) — die Form ist also seit Langem unter Jugendlichen verbreitet. Heute ist sie Alltagssprache, etwa in Beziehungs-Content („wie man mit einem vermeidenden Partner ernst redet“) oder als Status 진대중 im Messenger. Eine Erstverwendung ist nicht belegt.", "en": "Built from the first syllables of 진지한 대화. A 2013 news article already quoted teenagers saying 엄마랑 진대 때림 (“had a serious talk with mom”), so it has circulated among young people for a long time. Today it is everyday speech — relationship content talks about “how to have a 진대 with an avoidant partner”, and people set 진대중 as a messenger status. No first use is documented.", "es": "Formada con las primeras sílabas de 진지한 대화. Un artículo de 2013 ya citaba a adolescentes diciendo 엄마랑 진대 때림 (“tuve una charla seria con mamá”), así que circula entre jóvenes desde hace mucho. Hoy es habla cotidiana: el contenido sobre relaciones habla de “cómo tener un 진대 con una pareja evitativa” y hay quien pone 진대중 como estado en el chat. No consta su primer uso.", "ja": "「진지한 대화」の頭文字を取った略語。2013年の記事で10代が「엄마랑 진대 때림(ママと真剣な話した)」と使う例が紹介されており、以前から若者の間で使われていた。今では恋愛・人間関係のコンテンツで「回避型の恋人と진대する方法」のように使われるほど日常語になり、カカオトークの状態メッセージに「진대중」と書く人もいる。初出は確認されていない。", "vi": "Ghép từ âm đầu của 진지한 대화. Một bài báo năm 2013 đã dẫn lời học sinh nói 엄마랑 진대 때림 (“vừa nói chuyện nghiêm túc với mẹ”), nên từ này đã lưu hành trong giới trẻ từ lâu. Nay nó thành từ thường ngày — nội dung về tình cảm bàn “cách 진대 với người yêu kiểu né tránh”, và có người để trạng thái 진대중 trên ứng dụng nhắn tin. Không rõ lần dùng đầu tiên."}'::jsonb, '말을 꺼내기 전에 ''진대 좀 하자''라고 하면 지금부터는 농담이 아니라는 신호가 된다. 친구·연인·가족 사이에서 쓰는 가벼운 줄임말이라 회사 면담이나 윗사람과의 대화에는 쓰지 않는다. 표준국어대사전의 ''진대''(떼쓰며 괴롭히는 짓 등)와는 전혀 다른 말이다.', '{"de": "Wer vorab „진대 좀 하자“ sagt, signalisiert: Ab jetzt kein Spaß mehr. Es ist eine lockere Kurzform unter Freunden, Paaren und in der Familie — nicht für Mitarbeitergespräche oder Vorgesetzte. Mit dem Standardwörterbuch-Wort 진대 (z. B. „jemanden bedrängen“) hat es nichts zu tun.", "en": "Saying 진대 좀 하자 before you start signals that the jokes stop here. It is a casual clipping for friends, partners and family, so keep it out of work meetings or talks with superiors. It has nothing to do with the dictionary word 진대 (e.g. pestering someone).", "es": "Decir 진대 좀 하자 antes de empezar avisa de que se acabaron las bromas. Es una abreviatura informal entre amigos, parejas y familia, así que no la uses en reuniones de trabajo ni con superiores. No tiene nada que ver con la palabra de diccionario 진대 (p. ej. “fastidiar a alguien”).", "ja": "話を切り出す前に「진대 좀 하자」と言えば、ここからは冗談じゃないという合図になる。友達・恋人・家族の間で使う軽い略語なので、会社の面談や目上の人との会話には使わない。標準国語大辞典の「진대」(しつこくせがんで困らせること等)とは全く別の語。", "vi": "Nói 진대 좀 하자 trước khi vào chuyện là tín hiệu từ giờ không đùa nữa. Đây là từ rút gọn thân mật giữa bạn bè, người yêu, gia đình, nên không dùng trong buổi trao đổi ở công ty hay với cấp trên. Không liên quan gì đến từ 진대 trong từ điển chuẩn (như “đeo bám làm phiền”)."}'::jsonb, array['엄근진','진지스칸'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Serious talk / heart-to-heart"}, {"lang": "🇯🇵 JA", "text": "真剣な話、腹を割った話"}, {"lang": "🇨🇳 ZH", "text": "认真谈话、走心聊天"}, {"lang": "🇻🇳 VI", "text": "Nói chuyện nghiêm túc, tâm sự"}, {"lang": "🇪🇸 ES", "text": "Charla seria"}, {"lang": "🇩🇪 DE", "text": "Ernstes Gespräch"}]'::jsonb);

